#!/usr/bin/env node
// Copy API specs + generate the Swagger UI viewer into docs/public/api/
// so VitePress can serve them from the deployed site.
//
// Runs as a `predocs:dev` / `predocs:build` npm hook.
//
// Inputs (regenerated by `just openapi` / `just asyncapi`; the two
// JSON specs are committed to git so CI doesn't need a Rust toolchain
// to build docs):
//   ../resources/gen/openapi.json
//   ../resources/gen/asyncapi.json
//
// Outputs (gitignored, produced fresh each build):
//   public/api/openapi.json   — verbatim copy for Swagger UI to fetch
//   public/api/asyncapi.json  — verbatim copy served as raw download
//   public/api/openapi/       — self-hosted Swagger UI + wrapper HTML
//
// AsyncAPI has no rendered HTML viewer — the arch doc at
// `docs/architecture/message-bus-and-notifications.md` is the durable
// human-readable reference, and the raw JSON serves the machine
// consumers. See that doc's "API-reference rendering" section for the
// rationale (every AsyncAPI HTML renderer we evaluated groups by
// channel, so operations sharing a channel address are hard to
// distinguish visually).

import { mkdir, copyFile, access, writeFile, rm } from "node:fs/promises";
import { constants } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const DOCS_DIR = resolve(HERE, "..");
const REPO_ROOT = resolve(DOCS_DIR, "..");
const GEN_DIR = join(REPO_ROOT, "resources", "gen");
const OUT_DIR = join(DOCS_DIR, "public", "api");

const OPENAPI_SRC = join(GEN_DIR, "openapi.json");
const ASYNCAPI_SRC = join(GEN_DIR, "asyncapi.json");
const OPENAPI_OUT = join(OUT_DIR, "openapi.json");
const ASYNCAPI_OUT = join(OUT_DIR, "asyncapi.json");
const OPENAPI_HTML_OUT = join(OUT_DIR, "openapi");
const OPENAPI_HTML_INDEX = join(OPENAPI_HTML_OUT, "index.html");
const SWAGGER_UI_DIST = join(DOCS_DIR, "node_modules", "swagger-ui-dist");
const ASYNCAPI_HTML_OUT = join(OUT_DIR, "asyncapi");
const ASYNCAPI_HTML_INDEX = join(ASYNCAPI_HTML_OUT, "index.html");
const ASYNCAPI_RC_DIST = join(
  DOCS_DIR,
  "node_modules",
  "@asyncapi",
  "react-component",
);

async function exists(p) {
  try {
    await access(p, constants.R_OK);
    return true;
  } catch {
    return false;
  }
}

async function main() {
  await mkdir(OUT_DIR, { recursive: true });

  // --- OpenAPI: verbatim copy + Redoc HTML render ---
  if (!(await exists(OPENAPI_SRC))) {
    console.warn(
      `[prepare-specs] ${OPENAPI_SRC} missing — the API-Reference REST page will 404.\n` +
      `                Run \`just openapi\` (or the CI Rust step) first.`,
    );
  } else {
    await copyFile(OPENAPI_SRC, OPENAPI_OUT);
    console.log(`[prepare-specs] openapi.json → public/api/`);

    // Swagger UI: copy the prebuilt static assets from
    // `swagger-ui-dist` into public/api/openapi/ and stamp a small
    // index.html that points Swagger at ../openapi.json. Zero CDN
    // dependency — every asset the page needs is served from the
    // same origin as the OxiCloud docs site itself.
    await rm(OPENAPI_HTML_OUT, { recursive: true, force: true });
    await mkdir(OPENAPI_HTML_OUT, { recursive: true });

    // The four assets Swagger UI needs at runtime. We copy just these
    // (not the whole 30+ file package) to keep the deployed site slim.
    for (const asset of [
      "swagger-ui.css",
      "swagger-ui-bundle.js",
      "swagger-ui-standalone-preset.js",
      "favicon-32x32.png",
    ]) {
      await copyFile(
        join(SWAGGER_UI_DIST, asset),
        join(OPENAPI_HTML_OUT, asset),
      );
    }

    // The wrapper page. Loads Swagger UI locally (no CDN), points it
    // at the sibling openapi.json, and hides the top bar so the doc
    // reads clean inside the VitePress iframe.
    const swaggerHtml = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>OxiCloud REST API</title>
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <link rel="icon" type="image/png" sizes="32x32" href="./favicon-32x32.png" />
  <link rel="stylesheet" href="./swagger-ui.css" />
  <style>
    html, body { margin: 0; background: #fafafa; }
    .swagger-ui .topbar { display: none; }
  </style>
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="./swagger-ui-bundle.js" charset="UTF-8"></script>
  <script src="./swagger-ui-standalone-preset.js" charset="UTF-8"></script>
  <script>
    window.ui = SwaggerUIBundle({
      url: "../openapi.json",
      dom_id: "#swagger-ui",
      deepLinking: true,
      docExpansion: "list",
      defaultModelsExpandDepth: 1,
      presets: [SwaggerUIBundle.presets.apis, SwaggerUIStandalonePreset],
      plugins: [SwaggerUIBundle.plugins.DownloadUrl],
      layout: "StandaloneLayout",
    });
  </script>
</body>
</html>`;
    await writeFile(OPENAPI_HTML_INDEX, swaggerHtml, "utf8");
    console.log(`[prepare-specs] Swagger UI → public/api/openapi/`);
  }

  // --- AsyncAPI: verbatim JSON copy + rendered viewer via @asyncapi/react-component ---
  // Every AsyncAPI HTML renderer we evaluated (html-template,
  // react-component, Studio) collapses operations by channel — the
  // spec's data model puts operations under channels, so five ops
  // on `folder:{folderId}` render under identical section headers.
  // Not fixable in the renderer; would require splitting channels
  // per-operation in the spec. Rationale + review of alternatives
  // in `docs/architecture/message-bus-and-notifications.md`.
  //
  // Sticking with the react-component (also what AsyncAPI Studio
  // uses) because @asyncapi/html-template 3.x has a regression that
  // crashes even on a minimal spec when paired with @asyncapi/cli 6.x.
  if (!(await exists(ASYNCAPI_SRC))) {
    console.warn(
      `[prepare-specs] ${ASYNCAPI_SRC} missing — the API-Reference Bus page will 404.\n` +
      `                Run \`just asyncapi\` (or the CI Rust step) first.`,
    );
    return;
  }
  await copyFile(ASYNCAPI_SRC, ASYNCAPI_OUT);
  console.log(`[prepare-specs] asyncapi.json → public/api/`);

  await rm(ASYNCAPI_HTML_OUT, { recursive: true, force: true });
  await mkdir(ASYNCAPI_HTML_OUT, { recursive: true });

  await copyFile(
    join(ASYNCAPI_RC_DIST, "browser", "standalone", "index.js"),
    join(ASYNCAPI_HTML_OUT, "standalone.js"),
  );
  await copyFile(
    join(ASYNCAPI_RC_DIST, "styles", "default.min.css"),
    join(ASYNCAPI_HTML_OUT, "styles.css"),
  );

  const asyncapiHtml = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>OxiCloud Message Bus (AsyncAPI)</title>
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <link rel="stylesheet" href="./styles.css" />
  <style>html, body { margin: 0; }</style>
</head>
<body>
  <div id="asyncapi"></div>
  <script src="./standalone.js"></script>
  <script>
    AsyncApiStandalone.render({
      schema: { url: "../asyncapi.json" },
      config: {
        show: { sidebar: true, info: true, servers: true, operations: true, messages: true, schemas: true, errors: true },
        expand: { messageExamples: true },
      },
    }, document.getElementById("asyncapi"));
  </script>
</body>
</html>`;
  await writeFile(ASYNCAPI_HTML_INDEX, asyncapiHtml, "utf8");
  console.log(`[prepare-specs] AsyncAPI (react-component) → public/api/asyncapi/`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
